@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource/ibm-plex-mono/400.css";
@import "@fontsource/ibm-plex-mono/500.css";
@import "@fontsource-variable/oswald";
@import "@fontsource/instrument-serif";

/* Light (faithful): a white page, #f7f7f7 bands, #f4f4f4 panels, #f0f0f0 cards, near-black
   text (21,21,20), warm-grey body copy (105,103,101), pure black buttons, an electric blue
   (24,98,255) for mentions and eyebrows and a softer blue (79,127,255) as the glow. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.195 0.002 106);
  --card: oklch(0.97 0 0);
  --card-foreground: oklch(0.195 0.002 106);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.195 0.002 106);
  --primary: oklch(0 0 0);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.955 0 0);
  --secondary-foreground: oklch(0.195 0.002 106);
  --muted: oklch(0.979 0 0);
  --muted-foreground: oklch(0.52 0.004 67);
  --accent: oklch(0.95 0.025 270);
  --accent-foreground: oklch(0.195 0.002 106);
  --destructive: oklch(0.58 0.22 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0 0 0 / 10%);
  --input: oklch(0.88 0 0);
  --ring: oklch(0.56 0.24 262);
  --highlight: oklch(0.56 0.24 262);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.63 0.19 266);
  --chart-1: oklch(0.56 0.24 262);
  --chart-2: oklch(0.63 0.19 266);
  --chart-3: oklch(0.75 0.17 60);
  --chart-4: oklch(0.3 0.08 265);
  --chart-5: oklch(0.65 0.004 67);
  --sidebar: oklch(0.979 0 0);
  --sidebar-foreground: oklch(0.195 0.002 106);
  --sidebar-primary: oklch(0 0 0);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.955 0 0);
  --sidebar-accent-foreground: oklch(0.195 0.002 106);
  --sidebar-border: oklch(0 0 0 / 10%);
  --sidebar-ring: oklch(0.56 0.24 262);

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 1rem;
  --page-width: 90rem;
  --page-gutter: 1.25rem;
  --section-y: 5rem;

  /* not tokens: this site's two extra faces, read by its blocks with a display-face fallback */
  --eightsleep-figures: "Oswald Variable", "Arial Narrow", sans-serif-condensed, sans-serif;
  --eightsleep-quote: "Instrument Serif", Georgia, serif;
}

/* Dark: the site's night. True black, white text, white buttons with ink text, a deep navy
   (3,25,56) and a lighter navy (27,45,90) for the sky gradients, and a pale sky blue as the
   glow (it paints the hero's sky placeholder). */
.dark {
  --background: oklch(0 0 0);
  --foreground: oklch(1 0 0);
  --card: oklch(0.2 0.01 265);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.2 0.01 265);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(1 0 0);
  --primary-foreground: oklch(0.16 0.015 285);
  --secondary: oklch(0.2 0.06 258);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.18 0.005 265);
  --muted-foreground: oklch(0.78 0.005 265);
  --accent: oklch(0.31 0.08 266);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.68 0.2 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 15%);
  --input: oklch(1 0 0 / 22%);
  --ring: oklch(0.66 0.19 263);
  --highlight: oklch(0.66 0.19 263);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.68 0.08 250);
  --chart-1: oklch(0.66 0.19 263);
  --chart-2: oklch(0.68 0.08 250);
  --chart-3: oklch(0.78 0.16 60);
  --chart-4: oklch(0.45 0.1 265);
  --chart-5: oklch(0.78 0.005 265);
  --sidebar: oklch(0.12 0.01 265);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(1 0 0);
  --sidebar-primary-foreground: oklch(0.16 0.015 285);
  --sidebar-accent: oklch(0.2 0.06 258);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 15%);
  --sidebar-ring: oklch(0.66 0.19 263);
}
